package com.example.application_service.service;import com.example.application_service.entity.ApplicationStatus;import com.example.application_service.exception.ApiException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import java.util.*;
@Component public class ApplicationRules{private static final Map<ApplicationStatus,Set<ApplicationStatus>> ALLOWED=Map.of(ApplicationStatus.APPLIED,Set.of(ApplicationStatus.SCREENING,ApplicationStatus.REJECTED),ApplicationStatus.SCREENING,Set.of(ApplicationStatus.INTERVIEW,ApplicationStatus.REJECTED),ApplicationStatus.INTERVIEW,Set.of(ApplicationStatus.OFFER,ApplicationStatus.REJECTED),ApplicationStatus.OFFER,Set.of(ApplicationStatus.HIRED,ApplicationStatus.REJECTED),ApplicationStatus.HIRED,Set.of(),ApplicationStatus.REJECTED,Set.of());public void transition(ApplicationStatus from,ApplicationStatus to){if(!ALLOWED.getOrDefault(from,Set.of()).contains(to))throw new ApiException(HttpStatus.CONFLICT,"INVALID_STATUS_TRANSITION","Application status transition is not allowed");}}
